const releaseInboundEmailClaim = `-- name: ReleaseInboundEmailClaim :exec
UPDATE inbound_emails
SET
  processing_status = CASE
    WHEN discord_status IN ('posted', 'skipped')
      AND forwarding_status IN ('forwarded', 'skipped') THEN 'processed'
    ELSE 'failed'
  END,
  processed_at = CASE
    WHEN discord_status IN ('posted', 'skipped')
      AND forwarding_status IN ('forwarded', 'skipped') THEN NOW()
    ELSE processed_at
  END,
  next_attempt_at = CASE
    WHEN discord_status IN ('posted', 'skipped')
      AND forwarding_status IN ('forwarded', 'skipped') THEN next_attempt_at
    ELSE NOW() + LEAST(60, CAST(POWER(2, LEAST(processing_attempts, 6)) AS INTEGER)) * INTERVAL '1 minute'
  END,
  claim_until = NULL,
  updated_at = NOW()
WHERE id = $1
`

func (q *Queries) ReleaseInboundEmailClaim(ctx context.Context, id pgtype.UUID) error {
	_, err := q.db.Exec(ctx, releaseInboundEmailClaim, id)
	return err
}

